\begin{lemma}
\label{lemma-finite-length-finite}
\begin{slogan}
Modules of finite length are finite.
\end{slogan}
Let $R$ be a ring.
Let $M$ be an $R$-module.
If $\text{length}_R(M) < \infty$ then $M$ is a finite $R$-module.
\end{lemma}

\begin{proof}
Omitted.
\end{proof}

