\begin{definition}
\label{definition-simple-module}
Soit $R$ un anneau. Soit $M$ un $R$-module.
Nous disons que $M$ est {\it simple} si $M \not = 0$ et
tout sous-module de $M$ est soit égal à $M$, soit
à $0$.
\end{definition}

